const incoming = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const firstName = String(incoming.firstName || incoming.first_name || incoming.name || '').trim();
const lastName = String(incoming.lastName || incoming.last_name || '').trim();
const fullName = [firstName, lastName].filter(Boolean).join(' ') || 'Unknown visitor';
const email = String(incoming.email || '').trim() || 'N/A';
const phone = String(incoming.phone || '').trim() || 'N/A';

const pageUrl = String(
  incoming.pageUrl || incoming.page_url || incoming.url || incoming.websiteUrl || incoming.currentPage || ''
).trim() || 'N/A';
const referrer = String(incoming.referrer || incoming.referer || incoming.sourceUrl || '').trim() || 'N/A';
const eventType = String(incoming.eventType || incoming.event || incoming.trigger || 'Website Visitor Alert').trim();
const leadSource = String(incoming.leadSource || incoming.source || incoming.channel || 'Website').trim();

const utmSource = String(incoming.utmSource || incoming.utm_source || '').trim() || 'N/A';
const utmMedium = String(incoming.utmMedium || incoming.utm_medium || '').trim() || 'N/A';
const utmCampaign = String(incoming.utmCampaign || incoming.utm_campaign || '').trim() || 'N/A';

const happenedAtRaw = incoming.eventTime || incoming.timestamp || incoming.createdAt || incoming.created_at || new Date().toISOString();
const happenedAt = (() => {
  const dt = new Date(happenedAtRaw);
  return Number.isNaN(dt.getTime()) ? String(happenedAtRaw) : dt.toISOString();
})();

const text = [
  'New website visitor alert (#leads)',
  `Event: ${eventType}`,
  `Name: ${fullName}`,
  `Email: ${email}`,
  `Phone: ${phone}`,
  `Page: ${pageUrl}`,
  `Referrer: ${referrer}`,
  `Lead Source: ${leadSource}`,
  `UTM Source: ${utmSource}`,
  `UTM Medium: ${utmMedium}`,
  `UTM Campaign: ${utmCampaign}`,
  `Time: ${happenedAt}`
].join('\n');

return [{
  json: {
    text,
    sourcePayload: incoming
  }
}];

